from pathlib import Path
import os,json,subprocess,re,hashlib
R=Path(os.environ['PRIMER_OUT'])/'walkthrough';x=json.loads((R/'receipt.json').read_text());source=R/'live-interaction.webm';duration=round(x['recording']['seconds']*30)/30;meter=subprocess.run(['ffmpeg','-hide_banner','-i',str(source),'-af','silencedetect=noise=-45dB:d=1.2','-f','null','-'],capture_output=True,text=True,check=True).stderr;silences=list(zip([float(z) for z in re.findall(r'silence_start: ([-\d.]+)',meter)],[float(z) for z in re.findall(r'silence_end: ([-\d.]+)',meter)]));regions=[(silences[j][1],silences[j+1][0]) for j in range(len(silences)-1)];assert len(regions)==2

def stamp(t):
 ms=round(t*1000);h,ms=divmod(ms,3600000);m,ms=divmod(ms,60000);s,ms=divmod(ms,1000);return f'{h:02}:{m:02}:{s:02},{ms:03}'
subs=[];trans=[];n=0
for j,(e,(start,end)) in enumerate(zip(x['evidence'],regions)):
 text=e['sketch']['answer'];trans.append('Question: '+e['question']+'\n\n'+text);sentences=re.split(r'(?<=[.!?。])\s+',text);total=sum(len(s) for s in sentences);cursor=start
 for i,s in enumerate(sentences):
  stop=duration if j==1 and i==len(sentences)-1 else cursor+(end-start)*len(s)/total;n+=1;subs.append(f'{n}\n{stamp(cursor)} --> {stamp(stop)}\n{s}\n');cursor=stop
(R/'live-interaction.srt').write_text('\n'.join(subs));(R/'live-interaction.vtt').write_text('WEBVTT\n\n'+re.sub(r'(\d\d:\d\d:\d\d),(\d{3})',r'\1.\2','\n'.join(subs)));(R/'live-interaction-transcript.txt').write_text('\n\n'.join(trans));final=R/'live-interaction.mp4'
subprocess.run(['ffmpeg','-y','-v','error','-i',str(source),'-i',str(R/'live-interaction.srt'),'-map','0:v:0','-map','0:a:0','-map','1:0','-c:v','libx264','-preset','fast','-crf','21','-r','30','-pix_fmt','yuv420p','-vf','scale=out_range=tv,format=yuv420p,tpad=stop_mode=clone:stop_duration=1','-color_range','tv','-c:a','aac','-ar','48000','-b:a','160k','-af','apad,loudnorm=I=-16:TP=-2.0:LRA=11','-t',str(duration),'-c:s','mov_text','-metadata:s:s:0','language=eng','-movflags','+faststart',str(final)],check=True);subprocess.run(['ffmpeg','-v','error','-i',str(final),'-f','null','-'],check=True);probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(final)]));v=next(z for z in probe['streams'] if z['codec_type']=='video');a=next(z for z in probe['streams'] if z['codec_type']=='audio');drift=abs(float(v['duration'])-float(a['duration']));assert drift<=.1
meter=subprocess.run(['ffmpeg','-hide_banner','-i',str(final),'-af','ebur128=peak=true','-f','null','-'],capture_output=True,text=True,check=True).stderr;summary=meter[meter.rfind('Summary:'):];lufs=float(re.search(r'I:\s*(-?[\d.]+) LUFS',summary)[1]);peak=float(re.search(r'Peak:\s*(-?[\d.]+) dBFS',summary)[1]);assert -17<=lufs<=-15 and peak<=-1.5
(R/'live-interaction-qa.json').write_text(json.dumps({'sha256':hashlib.sha256(final.read_bytes()).hexdigest(),'bytes':final.stat().st_size,'fullDecodePassed':True,'avEndDriftSeconds':drift,'duration':duration,'actualSpeechRegions':regions,'loudnessLUFS':lufs,'truePeakDBFS':peak,'probe':probe,'scope':'Uncut live browser DOM interaction, actual generated voice; screenshots refreshed during capture, 30fps container is not a throughput claim','subtitleTiming':'Actual speech regions; sentence proportional approximate alignment; last caption held through final preview'},indent=2));subprocess.run(['ffmpeg','-y','-v','error','-i',str(final),'-map','0:a:0','-c:a','libmp3lame','-b:a','160k',str(R/'live-interaction.mp3')],check=True);print('walkthrough',duration,lufs,peak,drift)
